/**
 * The fruit that pile up during the landing intro: agrumeafarm.it's own
 * loader artwork — its eleven flat fruit, in their order, with the collision
 * outline it uses for each and its two size corrections — recoloured in the
 * app's palette. Only the colours are ours.
 *
 * Each fruit is its original SVG body, filled with `currentColor`, in its own
 * viewBox. The physics body is the convex hull of the original's collision
 * outline (matter-js falls back to the hull for concave outlines anyway, and
 * the drawing and the body stay aligned through the hull's centroid).
 */

type Point = [number, number];

export interface FruitDef {
  name: string;
  color: string;
  /** The artwork's viewBox size. */
  width: number;
  height: number;
  /** The original's size correction for this fruit, where it has one. */
  scale?: number;
  /** What collides, in viewBox units. */
  hull: Point[];
  /** The artwork, minus its <svg> element. Its clip ids are made unique per copy. */
  markup: string;
}

/**
 * The app's own palette, as hex because these SVGs are built as strings:
 * Tailwind's zinc scale plus the blue and lavender of `hero-wash`.
 */
