/** Area-weighted centroid of a simple polygon. */
export function centroid(points: Point[]): Point {
  let a = 0,
    cx = 0,
    cy = 0;
  for (let i = 0; i < points.length; i++) {
    const [x0, y0] = points[i];
    const [x1, y1] = points[(i + 1) % points.length];
    const f = x0 * y1 - x1 * y0;
    a += f;
    cx += (x0 + x1) * f;
    cy += (y0 + y1) * f;
  }
  a *= 0.5;
  return [cx / (6 * a), cy / (6 * a)];
}

/**
 * The fruit as an SVG string, filling its box.
 *
 * A string rather than a component: the intro creates these nodes itself,
 * because how big they are depends on the window, which the server render
 * can't know. `copy` keeps two copies of a fruit from sharing clip ids.
 */
export function fruitMarkup(fruit: FruitDef, copy: string): string {
  const markup = fruit.markup.replace(/(id="|url\(#)([^")]+)/g, `$1$2-${copy}`);
  return (
    `<svg viewBox="0 0 ${fruit.width} ${fruit.height}" width="100%" height="100%" aria-hidden="true" style="display:block;color:${fruit.color}">` +
    markup +
    `</svg>`
  );
}
